		fmt.Fprintln(w, reason)
	}
	if g.Quiet {
		return nil
	}
	fmt.Fprintln(w, lr.StatusLine())
	for _, m := range lr.Messages {
		unread := " "
		if m.Unread {
			unread = "*"
		}
		fmt.Fprintf(w, "%s [%s] %s — %s (%s)\n", unread, m.ID, m.From, m.Subject, m.Date)
	}
	return nil
}

