package mcp_test

// This is a throwaway feasibility spike for bead beadle-6i0.5. It proves that
// beadle's MCP library (github.com/mark3labs/mcp-go) supports the two moves the
// biff DES-004 "priming" pattern depends on:
//
//  1. change a registered tool's DESCRIPTION at runtime, and have a connected
//     client observe the new text; and
//  2. emit notifications/tools/list_changed to a connected session from BOTH a
//     background goroutine (the "suspenders" path) and a tool handler's context
//     (the "belt" path).
//
// Findings (see .tmp/missions/results/6i0-5-design.md):
//
//   - Runtime description change: SUPPORTED. AddTool overwrites the tool entry
//     keyed by name; a client's ListTools returns the new description.
//   - tools/list_changed from a background goroutine: SUPPORTED via
//     MCPServer.SendNotificationToAllClients (no session ref needed — the server
//     holds the session registry). AddTool/SetTools also fire it automatically,
//     so mutating the description and notifying are ONE call.
//   - tools/list_changed from a handler context: SUPPORTED via
//     MCPServer.SendNotificationToClient(ctx, ...).
//   - Caveat: the plain in-process client (client.NewInProcessClient) registers
//     no session and runs no notification pump, so it cannot OBSERVE server-push
//     notifications. Emission is therefore proven against a directly-registered
//     recording session — the same ClientSession contract a real transport
//     satisfies.

import (
	"context"
	"fmt"
	"sync/atomic"
	"testing"
	"time"

	mcplib "github.com/mark3labs/mcp-go/mcp"
	"github.com/mark3labs/mcp-go/client"
	"github.com/mark3labs/mcp-go/server"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// checkMailTool builds the priming tool whose description carries the repo's
// unread count. Re-registering it under the same name is the description edit.
func checkMailTool(unread int) mcplib.Tool {
	desc := fmt.Sprintf(
		"Check your beadle inbox and handle new mail (%d unread in this repo). Call to list unread messages.",
		unread,
	)
	return mcplib.NewTool("check_mail", mcplib.WithDescription(desc))
}

func spikeNoop(_ context.Context, _ mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	return mcplib.NewToolResultText("ok"), nil
}

// recordingSession is a ClientSession whose notification channel the test can
// read. A real transport's session is opaque from outside the server package;
// this stand-in satisfies the same interface so we can observe emission.
type recordingSession struct {
