// TestSpike_DescriptionChangeVisibleToClient proves requirement (a): a runtime
// description edit is visible to a connected client via ListTools.
func TestSpike_DescriptionChangeVisibleToClient(t *testing.T) {
	srv := server.NewMCPServer("beadle-spike", "test", server.WithToolCapabilities(true))
	srv.AddTool(checkMailTool(0), spikeNoop)

	c, err := client.NewInProcessClient(srv)
	require.NoError(t, err)
	defer c.Close()

	ctx := context.Background()
	require.NoError(t, c.Start(ctx))

	initReq := mcplib.InitializeRequest{}
	initReq.Params.ProtocolVersion = mcplib.LATEST_PROTOCOL_VERSION
	initReq.Params.ClientInfo = mcplib.Implementation{Name: "spike", Version: "test"}
	_, err = c.Initialize(ctx, initReq)
	require.NoError(t, err)

	before, err := c.ListTools(ctx, mcplib.ListToolsRequest{})
	require.NoError(t, err)
	require.Len(t, before.Tools, 1)
	assert.Contains(t, before.Tools[0].Description, "0 unread")

	// Re-register the same tool name with a new count. AddTool overwrites the
	// entry keyed by name, so the description changes in place.
	srv.AddTool(checkMailTool(3), spikeNoop)

	after, err := c.ListTools(ctx, mcplib.ListToolsRequest{})
	require.NoError(t, err)
	require.Len(t, after.Tools, 1)
	assert.Contains(t, after.Tools[0].Description, "3 unread")
}

// TestSpike_ToolListChangedEmission proves requirement (b): tools/list_changed
// reaches a connected session from both the suspenders and belt paths.
func TestSpike_ToolListChangedEmission(t *testing.T) {
	srv := server.NewMCPServer("beadle-spike", "test", server.WithToolCapabilities(true))

	sess := &recordingSession{id: "spike-session", ch: make(chan mcplib.JSONRPCNotification, 8)}
	require.NoError(t, srv.RegisterSession(context.Background(), sess))
	sess.Initialize() // only initialized sessions receive broadcasts

	t.Run("suspenders: background goroutine broadcast", func(t *testing.T) {
		go srv.SendNotificationToAllClients(mcplib.MethodNotificationToolsListChanged, nil)
		waitNotify(t, sess.ch, mcplib.MethodNotificationToolsListChanged)
	})

	t.Run("suspenders: re-registration auto-broadcasts", func(t *testing.T) {
		// Mutating the description via AddTool fires tools/list_changed on its
		// own — description edit and notification are one call.
		srv.AddTool(checkMailTool(5), spikeNoop)
		waitNotify(t, sess.ch, mcplib.MethodNotificationToolsListChanged)
	})

	t.Run("belt: targeted send from a handler context", func(t *testing.T) {
		// A tool handler receives a ctx carrying its ClientSession; this is the
		// exact call such a handler makes.
		ctx := srv.WithContext(context.Background(), sess)
		require.NoError(t, srv.SendNotificationToClient(ctx, mcplib.MethodNotificationToolsListChanged, nil))
		waitNotify(t, sess.ch, mcplib.MethodNotificationToolsListChanged)
	})
}

