	for i, ln := range lines {
		b := trimTerminator(ln)
		if isFence(b) {
			inFence = !inFence
			continue
		}
		if inFence || isIndented(b) {
			continue
		}
		fn(i, b)
	}
	return inFence
}

// endsInOpenFence reports whether lines finish inside an unclosed code fence.
