func isFence(body string) bool {
	s := strings.TrimLeft(body, " \t")
	return strings.HasPrefix(s, "```") || strings.HasPrefix(s, "~~~")
}

func isIndented(body string) bool {
	return strings.HasPrefix(body, "\t") || strings.HasPrefix(body, "    ")
}

